<div class="page-heading"><div><div class="eyebrow">DATA PROTECTION</div><h1>Database backups</h1><p>Create and download private MySQL database backups. Store copies off-server for disaster recovery.</p></div><form method="POST" action="<?php echo e(route('backups.create')); ?>" onsubmit="return confirm('Create a database backup now?')"><?php echo csrf_field(); ?><button class="btn btn-primary"><i class="bi bi-database-down me-2"></i>Create backup</button></form></div>
<div class="alert alert-info">Backup generation requires <code>mysqldump</code> to be installed and available to the PHP process. Automatic backups run daily at <?php echo e(\Illuminate\Support\Carbon::createFromFormat('H:i', config('app.backup_schedule_time', '01:30'))->format('g:i A')); ?> <?php echo e(config('app.timezone', 'Asia/Manila')); ?> when enabled in System Settings. Retention is applied after a successful scheduled backup. Store an additional copy off-server. This screen does not perform database restoration; use the documented restore drill against a separate test database before relying on backups.</div><div class="d-flex flex-wrap gap-2 mb-3"><a class="btn btn-outline-secondary btn-sm" href="<?php echo e(route('settings.index')); ?>"><i class="bi bi-gear me-1"></i>Configure backup policy</a><a class="btn btn-outline-secondary btn-sm" href="<?php echo e(route('backups.runbook')); ?>" target="_blank" rel="noopener"><i class="bi bi-journal-text me-1"></i>Restore runbook</a></div>
<div class="panel"><div class="panel-header"><div><h2>Backup history</h2><p><?php echo e($backups->total()); ?> stored backups</p></div></div><div class="table-responsive"><table class="table data-table align-middle mb-0"><thead><tr><th>Filename</th><th>Created by</th><th>Date</th><th>File size</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $backups; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $backup): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td class="mono"><?php echo e($backup->filename); ?></td><td><?php echo e($backup->creator?->name??'System'); ?></td><td><?php echo e($backup->created_at?->format(config('app.date_format', 'd M Y').' '.config('app.time_format', 'H:i'))); ?></td><td><?php echo e(number_format($backup->size_bytes/1024,1)); ?> KB</td><td><span class="status-pill active"><?php echo e($backup->status); ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?php echo e(route('backups.download',$backup)); ?>">Download</a><form class="d-inline" method="POST" action="<?php echo e(route('backups.destroy',$backup)); ?>" onsubmit="return confirm('Delete this backup file?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="6" class="empty-state">No backups have been created.</td></tr><?php endif; ?></tbody></table></div><div class="panel-footer"><?php echo e($backups->links()); ?></div></div>
